        : postJson<Person>(peoplePath(sheet), body),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: peopleKey(sheet) });
      if (editing) {
        onDone();
      } else {
        setName('');
        setGrade('A');
      }
    },
  });

  return (
    <form
      onSubmit={(e) => {
        e.preventDefault();
        save.reset();
        if (!name.trim()) {
          // Refused on the form; nothing is sent.
          save.mutate({ name, grade }, {}); // the server refuses it too; see below
          return;
        }
        save.mutate({ name, grade });
      }}
    >
      <label>
        Name{' '}
        <input
          data-testid="person-form-name"
          value={name}
          onChange={(e) => {
            save.reset();
            setName(e.target.value);
          }}
        />
      </label>{' '}
      <label>
        Grade{' '}
        <select
          data-testid="person-form-grade"
          value={grade}
          onChange={(e) => {
            save.reset();
            setGrade(e.target.value);
          }}
        >
          {GRADES.map((g) => (
            <option key={g} value={g}>
              {g}
            </option>
          ))}
        </select>
      </label>{' '}
      <button type="submit" data-testid="person-form-submit" disabled={save.isPending}>
        {editing ? 'Save' : 'Add'}
      </button>
      {editing && (
        <button type="button" onClick={onDone}>
          Cancel
        </button>
      )}
      {save.isError && (
        <span role="alert" data-testid="person-form-error">
          {' '}A name is required.
        </span>
      )}
    </form>
  );
}

import { createFileRoute } from '@tanstack/react-router';
import { SignIn, useCurrentUser } from '../features/session/SignIn';
import { SheetPicker, useSheetId } from '../features/session/SheetPicker';
import { SheetToday } from '../features/sheet/SheetToday';

// The one screen. Sign in by name, then load a sheet by id; everything else is per sheet.
export const Route = createFileRoute('/')({
  component: Home,
});

function Home() {
  const [user] = useCurrentUser();
  const sheet = useSheetId();
  return (
    <>
      <SignIn />
      {user && <SheetPicker />}
      {user && sheet && <SheetToday sheet={sheet} />}
      {user && !sheet && <p data-testid="home-empty">Nothing here yet.</p>}
    </>
  );
}

